using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public class SessionStore
{
    // Session state is stored in a cookie as base64 of a serialized object.
    public SessionState Load(string cookieValue)
    {
        var bytes = System.Convert.FromBase64String(cookieValue);
        using var ms = new MemoryStream(bytes);
        var formatter = new BinaryFormatter();
        var state = (SessionState)formatter.Deserialize(ms);
        return state;
    }

    public string Save(SessionState state)
    {
        using var ms = new MemoryStream();
        new BinaryFormatter().Serialize(ms, state);
        return System.Convert.ToBase64String(ms.ToArray());
    }
}

